"use client";
import LegacyPage from "../components/LegacyPage";

const TITLE = "Averages — Calendar";
const STYLE_CSS = "\n  /* ---------- Shared design system — copied verbatim from the other\n     top-level pages (/home//courses//contacts) so this reads\n     as the same app. See architecture-decisions.md re: promoting this to\n     an actual shared stylesheet once there's a build step. ----------\n     --cal-grid-bg / --cal-cell-alt are new here: per Martin (2026-09-04,\n     \"make the calendar white for non-dark mode and black and accsent\n     color for dark mode\"), the calendar grid itself needs to be a real\n     theme-aware surface rather than the flat black the wireframe showed\n     — white in light mode, near-black in dark mode, with the app's\n     existing fixed --accent color (unchanged by dark mode, same as\n     everywhere else in the app) doing the highlighting in both. */\n  :root {\n    --accent: #d94a2b;\n    --accent-dark: #a8331a;\n    --accent-ring: rgb(from var(--accent) r g b / 0.35);\n    --page-bg-start: #f17b53;\n    --page-bg-end: #930500;\n    --panel-bg: #eaeaec;\n    --panel-inner: #dcdce0;\n    --text-dark: #14151f;\n    --text-muted: #4b4d63;\n    --text-faint: #83849a;\n    --border: #cfcfd6;\n    --window-radius-lg: 22px;\n    --window-radius-md: 14px;\n    --window-radius-sm: 10px;\n    --grade-good: #2f7d54;\n    --grade-mid: #a67a22;\n    --grade-bad: #b6432f;\n    --cal-grid-bg: #ffffff;\n    --cal-cell-alt: #f4f4f6;\n  }\n\n  * { box-sizing: border-box; }\n\n  /* Scrollbars app-wide: a slim, permanently-visible, rounded gray bar\n     sitting slightly inset from the true edge of its scrollable area. */\n  * {\n    scrollbar-width: thin;\n    scrollbar-color: rgba(20, 21, 31, 0.28) transparent;\n  }\n  *::-webkit-scrollbar { width: 10px; height: 10px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb {\n    background-color: rgba(20, 21, 31, 0.28);\n    border-radius: 999px;\n    border: 2px solid transparent;\n    background-clip: padding-box;\n  }\n  *::-webkit-scrollbar-thumb:hover { background-color: rgba(20, 21, 31, 0.45); }\n  *::-webkit-scrollbar-corner { background: transparent; }\n\n  /* Declared so the browser themes ITS OWN chrome — scrollbars, the\n\n     overscroll gutter, form controls — against this page rather than\n\n     guessing. Without it Firefox drew a light-theme scrollbar over the\n\n     dark canvas and tinted it (Martin saw it as pink on a blue\n\n     background). LegacyPage's applyStoredTheme() updates both of these\n\n     to match whatever background the user actually saved. */\n\n  html {\n\n    color-scheme: dark;\n\n    background-color: #0c0c0e;\n\n  }\n\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    min-height: 100%;\n    font-family: \"puffin\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  }\n\n  body {\n    height: 100vh;\n    overflow: hidden;\n    /* Neutral black instead of a baked-in accent gradient here —\n       2026-09-11, per Martin. This is only ever visible for a split\n       second on reload/navigation, before applyStoredTheme() (or this\n       page's own appearance-reading script) sets the user's actual\n       saved background over it. The old default was the sample\n       red-orange gradient baked into this file, which read as a real\n       glitch flashing in between pages; a neutral black reads as\n       \"still loading\" instead, and matches the app's own Black\n       preset (#0c0c0e) so it's not a color that appears nowhere else\n       in the app. */\n    background-color: #0c0c0e;\n    background-image: none;\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    padding: 40px 24px 100px;\n    display: flex;\n    justify-content: center;\n  }\n\n  .page {\n    width: 100%;\n    max-width: 1100px;\n    align-self: stretch;\n    min-height: 0;\n    overflow-y: auto;\n    overflow-x: hidden;\n    display: flex;\n    flex-direction: column;\n  }\n\n  /* ---------- Top bar ---------- */\n  .topbar {\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    margin: 0 4px 18px;\n  }\n\n  h1.title {\n    color: #ffffff;\n    font-size: clamp(1.6rem, 3.4vw, 2.1rem);\n    font-weight: 900;\n    font-style: italic;\n    letter-spacing: -0.01em;\n    margin: 0;\n    transform: skewX(-2deg);\n    display: inline-block;\n  }\n  .subtitle {\n    color: rgba(255,255,255,0.85);\n    font-weight: 700;\n    font-style: italic;\n    font-size: 0.9rem;\n    margin: 2px 0 0 2px;\n  }\n\n  .profile-menu-wrap { position: relative; flex-shrink: 0; }\n  .profile-btn {\n    width: 42px;\n    height: 42px;\n    border-radius: 50%;\n    background: rgba(255,255,255,0.2);\n    border: 2px solid rgba(255,255,255,0.5);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.95rem;\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n  .profile-menu {\n    position: absolute;\n    top: calc(100% + 10px);\n    right: 0;\n    min-width: 160px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 25;\n  }\n  .profile-menu-item {\n    display: block;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.86rem;\n    color: var(--text-dark);\n    padding: 9px 12px;\n    cursor: pointer;\n  }\n  .profile-menu-item:hover { background: var(--panel-inner); }\n  .profile-menu-item.signout { color: var(--grade-bad); }\n\n  /* ---------- One card, mostly same as every other page — EXCEPT\n     height. Every other page's card force-stretches to fill the\n     viewport (flex: 1) because their content is naturally tall/variable.\n     Calendar's grid rows are now capped (see .cal-month-grid /\n     .cal-week-grid below), so forcing the card to full height left a\n     large empty panel below the grid on Month/Week view. Fix\n     (2026-09-08): let the card size to its own content instead\n     (flex: 0 1 auto) — it still can't overflow the viewport, because\n     .page above it keeps its own fixed, scrollable height, so a\n     genuinely tall view (Year) just scrolls the page rather than\n     stretching the card into blank space. ---------- */\n  .card {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    padding: 6px;\n    flex: 0 1 auto;\n    min-height: 0;\n    display: flex;\n    flex-direction: column;\n  }\n  .card-inner {\n    padding: 20px 20px 18px;\n    flex: 0 1 auto;\n    min-height: 0;\n    overflow-y: auto;\n    overflow-x: hidden;\n    display: flex;\n    flex-direction: column;\n  }\n\n  /* ---------- Calendar layout: sidebar (search/filters/selected event)\n     + main (toolbar + grid). Stacks to a single column on narrow\n     viewports — see the media query near the bottom.\n\n     Fix (2026-09-07): the grid used to be a small fixed-height block\n     sitting at the top of a card that's always stretched to fill the\n     viewport (same \"one card, same as every other page\" convention as\n     everywhere else) — on Week view, or any Month with a light events\n     week, that left a large dead grey rectangle below the grid with\n     nothing in it, which read as the page \"stretching\" oddly rather\n     than the calendar just being short. Now cal-layout/cal-main/calBody\n     all flex to fill the card's real height, so the grid itself grows\n     to fill the available space (see #calBody, .cal-grid-wrap,\n     .cal-month-grid, .cal-week-grid below) instead of floating above a\n     blank area. The sidebar stays top-aligned on purpose (its content\n     — search/selected-event — has no reason to stretch). ---------- */\n  .cal-layout { display: flex; gap: 18px; align-items: stretch; flex: 1; min-height: 0; }\n  .cal-sidebar { width: 240px; flex-shrink: 0; display: flex; flex-direction: column; gap: 16px; align-self: flex-start; }\n  .cal-main { flex: 1; min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 12px; }\n  #calBody { flex: 1; min-height: 0; display: flex; flex-direction: column; }\n\n  .cal-search-wrap { position: relative; }\n  .cal-search-wrap svg { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); width: 15px; height: 15px; stroke: var(--text-faint); fill: none; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; pointer-events: none; }\n  #calendarSearch {\n    width: 100%;\n    border: none;\n    border-radius: 999px;\n    background: var(--panel-inner);\n    padding: 9px 30px 9px 34px;\n    font: inherit;\n    font-size: 0.82rem;\n    color: var(--text-dark);\n  }\n  #calendarSearch::placeholder { color: var(--text-faint); }\n  #calendarSearch:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .cal-search-clear {\n    position: absolute; right: 6px; top: 50%; transform: translateY(-50%);\n    width: 22px; height: 22px; border-radius: 50%; border: none;\n    background: var(--border); color: var(--text-dark);\n    font-size: 0.7rem; line-height: 1; cursor: pointer;\n    display: flex; align-items: center; justify-content: center;\n  }\n  .cal-search-clear.is-hidden { display: none; }\n\n  .cal-filter-label { font-size: 0.72rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-faint); margin: 0 0 8px; }\n  .cal-filter-group { }\n  .cal-chip-list { display: flex; flex-wrap: wrap; gap: 6px; }\n  .cal-chip {\n    display: inline-flex; align-items: center; gap: 6px;\n    border: 1px solid var(--border);\n    background: var(--panel-inner);\n    border-radius: 999px;\n    padding: 5px 10px 5px 8px;\n    font: inherit;\n    font-size: 0.74rem;\n    font-weight: 700;\n    color: var(--text-dark);\n    cursor: pointer;\n    transition: opacity 0.12s ease;\n  }\n  .cal-chip .dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }\n  .cal-chip.inactive { opacity: 0.4; }\n  .cal-chip:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n\n  .cal-view-switch { display: flex; flex-shrink: 0; background: var(--panel-inner); border-radius: 999px; padding: 3px; gap: 2px; }\n  .cal-view-btn {\n    border: none; background: none; border-radius: 999px;\n    font: inherit; font-size: 0.76rem; font-weight: 800; color: var(--text-muted);\n    padding: 7px 12px; cursor: pointer; white-space: nowrap;\n  }\n  .cal-view-btn.active { background: var(--accent); color: #fff; }\n  .cal-view-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n\n  /* ---------- Selected Event panel ---------- */\n  .cal-selected-event { background: var(--panel-inner); border-radius: var(--window-radius-md); padding: 14px; }\n  .cal-selected-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }\n  .cal-selected-close {\n    width: 22px; height: 22px; border-radius: 50%; border: none;\n    background: var(--panel-bg); color: var(--text-muted);\n    font-size: 0.7rem; line-height: 1; cursor: pointer;\n  }\n  .cal-selected-close:hover { color: var(--text-dark); }\n  .cal-selected-close.is-hidden { display: none; }\n  .cal-selected-empty { font-size: 0.78rem; color: var(--text-faint); font-style: italic; margin: 0; }\n  .cal-selected-title { font-size: 0.94rem; font-weight: 800; font-style: italic; color: var(--text-dark); margin: 0 0 6px; letter-spacing: -0.005em; }\n  .cal-selected-course { display: flex; align-items: center; gap: 6px; font-size: 0.78rem; font-weight: 700; color: var(--text-muted); margin: 0 0 8px; }\n  .cal-selected-course .dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }\n  .cal-selected-badge {\n    display: inline-block; font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.03em;\n    color: var(--accent); border: 1px solid var(--accent); border-radius: 999px; padding: 2px 8px; margin-bottom: 10px;\n  }\n  /* Teacher-created events carry a \"who created it\" tooltip on the badge\n     (2026-09-08, per Martin). position:relative on the badge anchors the\n     absolutely-positioned .cal-tooltip; cursor:help + tabindex=\"0\" on the\n     badge signal it's interactive and keep it reachable by keyboard, and\n     the tooltip shows on :hover/:focus-visible so it works for mouse and\n     keyboard alike. It floats above the badge (bottom: 100%) since the\n     badge sits near the top of a fairly cramped sidebar panel. */\n  .cal-selected-badge.has-tooltip { position: relative; cursor: help; }\n  .cal-tooltip {\n    position: absolute;\n    bottom: calc(100% + 7px);\n    left: 50%;\n    transform: translateX(-50%);\n    background: var(--text-dark);\n    color: #fff;\n    font-size: 0.68rem;\n    font-weight: 700;\n    text-transform: none;\n    letter-spacing: normal;\n    white-space: nowrap;\n    border-radius: var(--window-radius-sm);\n    padding: 6px 10px;\n    box-shadow: 0 12px 30px -10px rgba(0,0,0,0.5);\n    opacity: 0;\n    visibility: hidden;\n    transition: opacity 0.12s ease;\n    pointer-events: none;\n    z-index: 20;\n  }\n  .cal-tooltip::after {\n    content: \"\";\n    position: absolute;\n    top: 100%;\n    left: 50%;\n    transform: translateX(-50%);\n    border: 5px solid transparent;\n    border-top-color: var(--text-dark);\n  }\n  .cal-selected-badge.has-tooltip:hover .cal-tooltip,\n  .cal-selected-badge.has-tooltip:focus-visible .cal-tooltip {\n    opacity: 1;\n    visibility: visible;\n  }\n  .cal-selected-row { display: flex; justify-content: space-between; gap: 10px; padding: 6px 0; border-bottom: 1px solid var(--border); font-size: 0.78rem; }\n  .cal-selected-row:last-of-type { border-bottom: none; }\n  .cal-selected-row .k { color: var(--text-faint); font-weight: 700; }\n  .cal-selected-row .v { color: var(--text-dark); font-weight: 700; text-align: right; }\n  .cal-selected-desc { font-size: 0.78rem; color: var(--text-muted); line-height: 1.45; margin: 10px 0 0; }\n  .cal-selected-actions { margin-top: 12px; }\n  .cal-selected-view-btn {\n    display: block; width: 100%; text-align: center;\n    background: var(--accent); color: #fff; border: none; border-radius: 999px;\n    padding: 9px; font: inherit; font-weight: 800; font-size: 0.8rem; cursor: pointer; text-decoration: none;\n  }\n  .cal-selected-view-btn:hover { background: var(--accent-dark); }\n\n  /* ---------- Main toolbar ---------- */\n  /* Fixed in place (2026-09-08, per Martin: \"make it so the week month\n     year is fixed in one place\") — .card-inner is the actual scrolling\n     container (see below), and this toolbar used to just be a normal\n     child of it, so it scrolled away with the grid on any view whose\n     content runs taller than the visible card (Year view especially, and\n     a tall Month). Sticking it to the top of that scroll container means\n     the Week/Month/Year switch — and Prev/Next/Today/Filters next to it —\n     stay in one place no matter how far you scroll the grid underneath.\n     Needs its own background since .card-inner has none of its own (it\n     shows .card's background through) — otherwise scrolled-past content\n     would show through behind it. */\n  .cal-toolbar {\n    display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap;\n    position: sticky; top: 0; z-index: 5;\n    background: var(--panel-bg);\n    flex-shrink: 0;\n  }\n  .cal-toolbar-left { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n  .cal-toolbar-right { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n  .cal-nav { display: flex; align-items: center; gap: 10px; }\n  .cal-nav-btn {\n    width: 30px; height: 30px; border-radius: 50%; border: none;\n    background: var(--panel-inner); color: var(--text-dark);\n    font-size: 1rem; font-weight: 800; cursor: pointer;\n    display: flex; align-items: center; justify-content: center;\n  }\n  .cal-nav-btn:hover { background: var(--border); }\n  .cal-header-label { font-size: 1.05rem; font-weight: 800; font-style: italic; color: var(--text-dark); margin: 0; min-width: 130px; text-align: center; letter-spacing: -0.005em; }\n  .cal-today-btn {\n    background: var(--panel-inner); color: var(--text-dark); border: none; border-radius: 999px;\n    padding: 7px 14px; font: inherit; font-weight: 800; font-size: 0.76rem; cursor: pointer;\n  }\n  .cal-today-btn:hover { background: var(--border); }\n\n  /* ---------- Filter dropdown — Source + Created By chips, moved here\n     from the sidebar (2026-09-04, per Martin) and consolidated into one\n     popover next to the Today button, same absolute-positioned-panel\n     pattern as the profile menu. ---------- */\n  .cal-filter-dropdown-wrap { position: relative; flex-shrink: 0; }\n  .cal-filter-btn {\n    display: flex; align-items: center; gap: 7px;\n    background: var(--panel-inner); color: var(--text-dark); border: none; border-radius: 999px;\n    padding: 7px 14px; font: inherit; font-weight: 800; font-size: 0.76rem; cursor: pointer;\n  }\n  .cal-filter-btn:hover { background: var(--border); }\n  .cal-filter-btn svg { width: 13px; height: 13px; stroke: currentColor; fill: none; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }\n  .cal-filter-active-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); flex-shrink: 0; }\n  .cal-filter-active-dot.is-hidden { display: none; }\n  .cal-filter-panel {\n    position: absolute; top: calc(100% + 10px); right: 0;\n    width: 230px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 14px;\n    display: flex; flex-direction: column; gap: 14px;\n    z-index: 25;\n  }\n  .cal-filter-panel.is-hidden { display: none; }\n\n  /* ---------- The grid surface itself — this is what Martin asked to be\n     theme-aware: white in light mode, near-black with the app's fixed\n     accent color for structure/highlights in dark mode. ---------- */\n  .cal-grid-wrap {\n    background: var(--cal-grid-bg);\n    border: 1px solid var(--border);\n    border-radius: var(--window-radius-md);\n    overflow: hidden;\n    flex: 1;\n    min-height: 0;\n    display: flex;\n    flex-direction: column;\n  }\n  .cal-dow-row { display: grid; grid-template-columns: repeat(7, 1fr); border-bottom: 1px solid var(--border); flex-shrink: 0; }\n  .cal-dow-cell { text-align: center; font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.04em; color: var(--accent); padding: 8px 2px; }\n\n  /* flex:1 + min-height:0 so the grid fills whatever's left of\n     .cal-grid-wrap instead of leaving a big blank margin below the last\n     row. Capped at 120px per row (2026-09-08, was an unbounded 1fr —\n     on a tall viewport that stretched every day cell absurdly tall;\n     120px is enough to comfortably hold 3-4 event chips without\n     ballooning). align-content:start means any space left over once\n     rows hit that cap just sits as blank surface below the grid,\n     inside the card, instead of stretching cells further. */\n  .cal-month-grid { display: grid; grid-template-columns: repeat(7, 1fr); grid-auto-rows: minmax(84px, 120px); flex: 1; min-height: 0; overflow-y: auto; align-content: start; }\n  .cal-day-cell {\n    min-height: 84px;\n    min-width: 0; /* grid items default to min-width:auto, which lets a\n      long unbroken event title (e.g. \"Colonial Timeline Presentations\")\n      force its whole column wider than the 1fr track and push the last\n      column off the edge of the card — this is what actually lets the\n      chip's own white-space:nowrap + text-overflow:ellipsis take over\n      instead. */\n    border-right: 1px solid var(--border);\n    border-bottom: 1px solid var(--border);\n    padding: 5px 5px 4px;\n    display: flex; flex-direction: column; gap: 3px;\n    background: var(--cal-grid-bg);\n  }\n  .cal-month-grid .cal-day-cell:nth-child(7n) { border-right: none; }\n  .cal-day-cell.outside { background: var(--cal-cell-alt); }\n  .cal-day-cell.outside .cal-day-num { color: var(--text-faint); }\n  .cal-day-num {\n    align-self: flex-start;\n    font-size: 0.76rem; font-weight: 800; color: var(--text-dark);\n    width: 22px; height: 22px; border-radius: 50%;\n    display: flex; align-items: center; justify-content: center;\n  }\n  .cal-day-cell.is-today .cal-day-num { background: var(--accent); color: #fff; }\n  /* Selected-event location highlight (2026-09-04, per Martin: \"make it\n     more apparent where it is\"). The whole day/week cell gets an accent\n     ring — not just the chip — so the selection still reads clearly even\n     when the matching chip itself is folded into a \"+N more\" popover. */\n  .cal-day-cell.has-selected { box-shadow: inset 0 0 0 2px var(--accent); position: relative; z-index: 1; }\n  .cal-day-events { display: flex; flex-direction: column; gap: 2px; overflow: hidden; }\n  .cal-event-chip {\n    display: block; width: 100%; min-width: 0; text-align: left; border: none;\n    background: color-mix(in srgb, var(--chip-color, var(--accent)) 18%, transparent);\n    border-left: 3px solid var(--chip-color, var(--accent));\n    color: var(--text-dark);\n    border-radius: 4px;\n    padding: 2px 5px;\n    font: inherit; font-size: 0.65rem; font-weight: 700;\n    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n    cursor: pointer;\n  }\n  .cal-event-chip.school { border-left-style: dashed; font-style: italic; }\n  .cal-event-chip.selected {\n    background: var(--chip-color, var(--accent));\n    color: #fff;\n    box-shadow: 0 0 0 2px var(--cal-grid-bg), 0 0 0 3.5px var(--chip-color, var(--accent));\n  }\n  .cal-day-more {\n    background: none; border: none; font: inherit; font-size: 0.62rem; font-weight: 800;\n    color: var(--text-faint); text-align: left; padding: 0 5px; cursor: pointer;\n  }\n  .cal-day-more:hover { color: var(--text-dark); }\n\n  /* ---------- Week view ---------- */\n  /* flex:1 lets this single-row grid grow to fill .cal-grid-wrap instead\n     of stopping at min-height and leaving the rest of the card empty\n     below it — but capped at 320px (2026-09-08; was unbounded, which on\n     a tall viewport stretched the single week-row to 500px+). Explicit\n     grid-template-rows (not grid-auto-rows — there's only ever one row\n     here) plus align-content:start means growth stops at the cap and any\n     further leftover height is blank surface below the row, not more\n     row-stretching. */\n  .cal-week-grid { display: grid; grid-template-columns: repeat(7, 1fr); grid-template-rows: minmax(220px, 260px); flex: 1; min-height: 0; align-content: start; }\n  .cal-week-cell {\n    min-height: 220px;\n    min-width: 0;\n    border-right: 1px solid var(--border);\n    padding: 6px 6px 8px;\n    display: flex; flex-direction: column; gap: 4px;\n    background: var(--cal-grid-bg);\n  }\n  .cal-week-grid .cal-week-cell:last-child { border-right: none; }\n  .cal-week-cell .cal-day-events { overflow-y: auto; }\n  .cal-week-cell.has-selected { box-shadow: inset 0 0 0 2px var(--accent); position: relative; z-index: 1; }\n\n  /* ---------- Year view ---------- */\n  .cal-year-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; padding: 14px; }\n  .cal-mini-month {\n    background: var(--cal-cell-alt);\n    border: 1px solid var(--border);\n    border-radius: var(--window-radius-sm);\n    padding: 8px;\n    cursor: pointer;\n  }\n  .cal-mini-month:hover { border-color: var(--accent); }\n  .cal-mini-month-label { font-size: 0.72rem; font-weight: 800; color: var(--text-dark); text-align: center; margin: 0 0 6px; }\n  .cal-mini-dow-row, .cal-mini-week-row { display: grid; grid-template-columns: repeat(7, 1fr); }\n  .cal-mini-dow { text-align: center; font-size: 0.5rem; font-weight: 800; color: var(--text-faint); }\n  .cal-mini-day { position: relative; text-align: center; font-size: 0.56rem; font-weight: 700; color: var(--text-muted); padding: 2px 0; }\n  .cal-mini-day.outside { color: transparent; }\n  .cal-mini-day.is-today { color: #fff; }\n  .cal-mini-day.is-today::before {\n    content: ''; position: absolute; inset: 1px 15% ; background: var(--accent); border-radius: 50%; z-index: -1;\n  }\n  .cal-mini-day.has-event::after {\n    content: ''; position: absolute; bottom: 0; left: 50%; transform: translateX(-50%);\n    width: 3px; height: 3px; border-radius: 50%; background: var(--accent);\n  }\n  .cal-mini-day.has-selected { box-shadow: 0 0 0 1.5px var(--accent); border-radius: 50%; }\n\n  .cal-empty-note { font-size: 0.8rem; color: var(--text-faint); font-style: italic; padding: 18px; text-align: center; }\n  /* Signed in, when the events didn't (all) load (2026-10-06). */\n  .cal-live-note { margin: 0; font-size: 0.78rem; font-weight: 700; color: var(--text-faint); }\n  .cal-live-note[hidden] { display: none; }\n  .cal-week-empty { font-size: 0.66rem; color: var(--text-faint); font-style: italic; padding: 6px 0 0; text-align: center; overflow-wrap: break-word; }\n\n  /* ---------- Search results (flat list, replaces the grid while a\n     search query is active) ---------- */\n  .cal-search-results { display: flex; flex-direction: column; }\n  .cal-search-row {\n    display: flex; align-items: center; gap: 10px; padding: 10px 4px;\n    border-bottom: 1px solid var(--border); cursor: pointer; background: none; border-left: none; border-right: none; border-top: none;\n    width: 100%; text-align: left; font: inherit;\n  }\n  .cal-search-row:last-child { border-bottom: none; }\n  .cal-search-row:hover { background: var(--panel-inner); }\n  .cal-search-row.selected { background: var(--panel-inner); box-shadow: inset 3px 0 0 var(--accent); }\n  .cal-search-row .dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }\n  .cal-search-row-text { flex: 1; min-width: 0; }\n  .cal-search-row-title { font-weight: 800; font-size: 0.84rem; color: var(--text-dark); margin: 0; }\n  .cal-search-row-meta { font-size: 0.72rem; color: var(--text-faint); margin: 2px 0 0; }\n\n  /* ---------- Day popover modal — same .modal-overlay/.modal-box\n     component as /contacts / /course-home. ---------- */\n  .modal-overlay {\n    position: fixed; inset: 0; background: rgba(10, 8, 6, 0.55);\n    display: flex; align-items: center; justify-content: center;\n    padding: 20px; z-index: 60;\n    opacity: 0; visibility: hidden; transition: opacity 0.15s ease;\n  }\n  .modal-overlay.show { opacity: 1; visibility: visible; }\n  .modal-box {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    max-width: 380px; width: 100%;\n    padding: 22px 24px;\n    box-shadow: 0 30px 70px -20px rgba(0,0,0,0.6);\n    transform: translateY(8px);\n    transition: transform 0.15s ease;\n    max-height: 80vh;\n    display: flex;\n    flex-direction: column;\n  }\n  .modal-overlay.show .modal-box { transform: translateY(0); }\n  .modal-close {\n    float: right;\n    background: var(--panel-inner);\n    border: none;\n    width: 26px; height: 26px;\n    border-radius: 50%;\n    color: var(--text-muted);\n    cursor: pointer;\n    font-size: 0.9rem;\n    line-height: 1;\n  }\n  .modal-close:hover { color: var(--text-dark); }\n  .modal-box h3 { margin: 0; font-size: 1.05rem; font-weight: 900; font-style: italic; color: var(--text-dark); clear: both; padding-top: 4px; }\n  #dayModalList { margin-top: 12px; overflow-y: auto; }\n\n  /* ---------- Bottom nav — verbatim from every other page ---------- */\n  .app-nav {\n    position: fixed;\n    left: 0;\n    right: 0;\n    bottom: 20px;\n    display: flex;\n    justify-content: center;\n    padding: 0 20px;\n    z-index: 10;\n    pointer-events: none;\n  }\n  .app-nav-inner {\n    display: flex;\n    gap: 4px;\n    width: 100%;\n    max-width: 940px;\n    overflow-x: auto;\n    scrollbar-width: none;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    padding: 0 8px;\n    pointer-events: auto;\n  }\n  .app-nav-inner::-webkit-scrollbar { display: none; }\n  .nav-link {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 1;\n    min-width: 0;\n    padding: 12px 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-link .label { display: block; max-width: 100%; font-size: 0.72rem; font-weight: 800; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; }\n  .nav-link:hover .label { color: var(--text-muted); }\n  .nav-link .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-link.active .label { color: var(--text-dark); }\n  .nav-link.active .dot { background: var(--accent); }\n  /* ---------- \"More\" overflow (2026-10-01, per Martin: \"if the text has\n     to get ... we should add a more button on the far right side with a\n     list of the other options\"). Labels never truncate: when they would,\n     the rightmost pages move into the More menu instead. ---------- */\n  .nav-link[hidden], .nav-more[hidden], .nav-more-menu[hidden] { display: none; }\n  /* While the More menu is open the whole bar sits above everything else on\n     the page (sticky headers, pop-ups, the edit button go up to z-index 90),\n     so the menu is never drawn underneath them. */\n  .app-nav.more-open { z-index: 1000; }\n  .nav-more {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 0 0 auto;\n    position: relative;\n    margin-left: 4px;\n    padding: 12px 16px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-more .label { display: flex; align-items: center; height: 1.2em; font-size: 0.72rem; color: var(--text-faint); }\n  .nav-more .label svg { display: block; fill: currentColor; }\n  /* thin divider between the pages and the dots */\n  .nav-more::before { content: \"\"; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: var(--border, #cfcfd6); }\n  .nav-more:hover .label, .nav-more[aria-expanded=\"true\"] .label { color: var(--text-dark); }\n  .nav-more .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-more.has-active .label { color: var(--text-dark); }\n  .nav-more.has-active .dot { background: var(--accent); }\n  .nav-more:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-menu {\n    position: absolute;\n    bottom: calc(100% + 8px);\n    right: 20px;\n    min-width: 168px;\n    padding: 8px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);\n    pointer-events: auto;\n  }\n  .nav-more-item {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    font-size: 0.8rem;\n    font-weight: 800;\n    color: var(--text-faint);\n    text-align: left;\n    padding: 12px 12px;\n    border-radius: 8px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n  }\n  .nav-more-item:hover, .nav-more-item:focus-visible { outline: none; color: var(--text-dark); box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-item.active { color: var(--text-dark); }\n  .nav-more-item.active span { position: relative; display: inline-block; padding-bottom: 6px; margin-bottom: -6px; }\n  .nav-more-item.active span::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  /* Labels sit centered in the bar; the active page is underlined in the\n     accent color instead of marked with a dot (2026-10-01, per Martin). */\n  .app-nav-inner .nav-link, .app-nav-inner .nav-more { justify-content: center; gap: 0; padding-top: 10px; padding-bottom: 10px; }\n  .app-nav-inner .nav-link .dot, .app-nav-inner .nav-more .dot { display: none; }\n  .app-nav-inner .nav-link .label, .app-nav-inner .nav-more .label { position: relative; padding: 6px 0; }\n  .app-nav-inner .nav-link.active .label::after, .app-nav-inner .nav-more.has-active .label::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  @media (max-width: 520px) {\n    .nav-more { padding: 10px 12px 8px; }\n    .nav-more::before { top: 10px; bottom: 10px; }\n    .app-nav-inner .nav-link, .app-nav-inner .nav-more { padding-top: 8px; padding-bottom: 8px; }\n    .nav-more .label { font-size: 0.58rem; }\n  }\n  .nav-link:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n\n  @media (max-width: 760px) {\n    .cal-layout { flex-direction: column; }\n    .cal-sidebar { width: 100%; }\n    .cal-year-grid { grid-template-columns: repeat(2, 1fr); }\n    .cal-day-cell { min-height: 64px; }\n    .cal-event-chip { font-size: 0.6rem; }\n  }\n  @media (max-width: 520px) {\n    .nav-link { min-width: 0; padding: 10px 3px 8px; }\n    .nav-link .label { font-size: 0.58rem; }\n    .cal-header-label { min-width: 0; font-size: 0.92rem; }\n    .cal-view-btn { padding: 7px 9px; font-size: 0.7rem; }\n    .cal-today-btn, .cal-filter-btn { padding: 7px 10px; font-size: 0.7rem; }\n    .cal-filter-panel { width: 200px; }\n    .cal-week-cell { min-height: 160px; }\n    /* Two mini-months per row leaves each day cell only ~10px wide —\n       too tight for two-digit dates (they visually run together). One\n       per row gives them room to breathe on phone-width screens. */\n    .cal-year-grid { grid-template-columns: 1fr; }\n  }\n";
const BODY_HTML = "\n  <div class=\"page\">\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\">Calendar</h1>\n        <p class=\"subtitle\">All your classes, one schedule</p>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\">M</button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-inner\">\n        <div class=\"cal-layout\">\n          <aside class=\"cal-sidebar\">\n            <div class=\"cal-search-wrap\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.35-4.35\"/></svg>\n              <input type=\"search\" id=\"calendarSearch\" placeholder=\"Search events\" autocomplete=\"off\" aria-label=\"Search calendar events\">\n              <button class=\"cal-search-clear is-hidden\" id=\"calendarSearchClear\" type=\"button\" aria-label=\"Clear search\">✕</button>\n            </div>\n\n            <div class=\"cal-selected-event\">\n              <div class=\"cal-selected-head\">\n                <p class=\"cal-filter-label\" style=\"margin:0;\">Selected Event</p>\n                <button class=\"cal-selected-close is-hidden\" id=\"selectedCloseBtn\" type=\"button\" aria-label=\"Clear selected event\">✕</button>\n              </div>\n              <div id=\"selectedEventBody\">\n                <p class=\"cal-selected-empty\">Tap any event on the calendar to see its details here.</p>\n              </div>\n            </div>\n          </aside>\n\n          <div class=\"cal-main\">\n            <div class=\"cal-toolbar\">\n              <div class=\"cal-toolbar-left\">\n                <div class=\"cal-nav\">\n                  <button class=\"cal-nav-btn\" id=\"calPrevBtn\" type=\"button\" aria-label=\"Previous\">‹</button>\n                  <h2 class=\"cal-header-label\" id=\"calHeaderLabel\"></h2>\n                  <button class=\"cal-nav-btn\" id=\"calNextBtn\" type=\"button\" aria-label=\"Next\">›</button>\n                </div>\n                <div class=\"cal-view-switch\" id=\"viewSwitch\">\n                  <button class=\"cal-view-btn\" type=\"button\" data-view=\"week\">Week</button>\n                  <button class=\"cal-view-btn active\" type=\"button\" data-view=\"month\">Month</button>\n                  <button class=\"cal-view-btn\" type=\"button\" data-view=\"year\">Year</button>\n                </div>\n              </div>\n              <div class=\"cal-toolbar-right\">\n                <button class=\"cal-today-btn\" id=\"calTodayBtn\" type=\"button\">Today</button>\n                <div class=\"cal-filter-dropdown-wrap\">\n                  <button class=\"cal-filter-btn\" id=\"filterBtn\" type=\"button\" aria-haspopup=\"true\" aria-expanded=\"false\">\n                    <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 5h18l-7 8v6l-4 2v-8z\"/></svg>\n                    Filters\n                    <span class=\"cal-filter-active-dot is-hidden\" id=\"filterActiveDot\"></span>\n                  </button>\n                  <div class=\"cal-filter-panel is-hidden\" id=\"filterPanel\">\n                    <div class=\"cal-filter-group\">\n                      <p class=\"cal-filter-label\">Source</p>\n                      <div class=\"cal-chip-list\" id=\"sourceChips\"></div>\n                    </div>\n                    <div class=\"cal-filter-group\">\n                      <p class=\"cal-filter-label\">Created By</p>\n                      <div class=\"cal-chip-list\" id=\"typeChips\"></div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <p class=\"cal-live-note\" id=\"calLiveNote\" role=\"status\" hidden></p>\n            <div id=\"calBody\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"modal-overlay\" id=\"dayModal\">\n    <div class=\"modal-box\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"dayModalTitle\">\n      <button class=\"modal-close\" id=\"dayModalCloseBtn\" type=\"button\" aria-label=\"Close\">✕</button>\n      <h3 id=\"dayModalTitle\"></h3>\n      <div id=\"dayModalList\"></div>\n    </div>\n  </div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\" id=\"dock\">\n      <button class=\"nav-link\" type=\"button\" data-page=\"home\" data-href=\"/home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"grades\" data-href=\"/grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"assignments\" data-href=\"/assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"files\" data-href=\"/files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link active\" type=\"button\" data-page=\"calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"messages\" data-href=\"/messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"contacts\" data-href=\"/contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n\n  \n  \n";
const SCRIPT_JS = "\n    // Potato PC Mode on every page (2026-10-04, per Martin). The saved\n    // setting turns off all CSS animations and transitions, makes animate()\n    // calls and smooth scrolling instant, and drops the slanted page title.\n    // Same code as app/lib/theme-boot.ts, which runs it before first paint in\n    // the app; this copy covers the preview and pages theme-boot skips.\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"schoolagy_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'schoolagy_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    // ------------------------------------------------------------------\n    // Shared appearance (accent + background) — 2026-09-08, per Martin:\n    // \"wallpapers + accent colors don't save across pages.\" Settings'\n    // Appearance section (and onboarding's Theme step) are the only\n    // writers of schoolagy_appearance; every other real app page,\n    // including this one, applies whatever's saved there, read-only, on\n    // its own load — same shared-localStorage-record pattern already\n    // used for schoolagy_dark_mode/schoolagy_profile.\n    // ------------------------------------------------------------------\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('schoolagy_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'schoolagy_appearance') applyAppearance();\n      });\n    })();\n\n    // ------------------------------------------------------------------\n    // Sample data (2026-09-04, per Martin's Calendar.pdf wireframe: \"add\n    // anything you want\"). Courses/colors reused verbatim from\n    // /home//contacts so this reads as the same six classes\n    // everywhere in the app. EVENTS spans late Aug through early Oct\n    // 2026 — the seven items flagged with `assignmentTitle` are the\n    // exact same entries /assignments already lists, so their\n    // \"View Assignment\" button deep-links into a real /assignment\n    // record instead of a generic fallback.\n    // ------------------------------------------------------------------\n\n    // ------------------------------------------------------------------\n    // Course customization persistence — added 2026-09-08. Renaming,\n    // recoloring, or reordering a course (in /home's Customize editor\n    // or /courses's Reorder tool — the only places that WRITE these)\n    // used to be invisible everywhere else, since every page just\n    // re-generated its own hardcoded COURSES array from scratch on load.\n    // schoolagy_course_custom holds per-course name/color overrides\n    // (object keyed by course id, only actually-customized courses\n    // present); schoolagy_course_order holds a full custom ordering of\n    // course ids (array), written only once the user has actually\n    // reordered. This page only READS both — applyCourseCustomizationsInPlace()\n    // is called right after the raw array literal below, mutating COURSES\n    // in place, so it's already the customized/reordered version before\n    // anything on this page ever renders it. Same defensive\n    // try/catch-per-key style as AVERAGES_DARK_MODE_KEY in /settings.\n    // ------------------------------------------------------------------\n    const AVERAGES_COURSE_CUSTOM_KEY = 'schoolagy_course_custom';\n    const AVERAGES_COURSE_ORDER_KEY = 'schoolagy_course_order';\n    function loadCourseCustom() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_CUSTOM_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return {};\n    }\n    function loadCourseOrder() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_ORDER_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return null;\n    }\n    // Subject table (2026-10-01, per Martin): each course gets a color that\n    // fits its subject, picked from its name. First match wins, so specific\n    // subjects come before broad ones (\"Computer Science\" before \"Science\",\n    // \"Physical Education\" before \"Physics\"). A color the student picked in\n    // the course's info pop-up still wins over this. No match keeps the\n    // course's own color. All colors pass 4.5:1 with white text.\n    const COURSE_SUBJECTS = [\n      [/\\bchem/, '🧪', '#1b7f67'],\n      [/\\bbio|anatom|physiolog/, '🧬', '#387f33'],\n      [/\\bphysical ed|(^|[^a-z])p\\.?e\\.?($|[^a-z])|fitness|\\bweight/, '🏃', '#c2562b'],\n      [/\\bhealth/, '🩺', '#c0404a'],\n      [/\\bphysics/, '⚛️', '#4a56b8'],\n      [/astronom/, '🔭', '#3b3f8f'],\n      [/environment|\\bearth|geolog/, '🌍', '#2f7f63'],\n      [/robotic/, '🤖', '#55697d'],\n      [/computer|programming|coding|\\bcs[ap]?\\b|software/, '💻', '#2d6f8f'],\n      [/engineer/, '⚙️', '#6a6478'],\n      [/government|civics|politic/, '🏛️', '#2f4f8a'],\n      [/econ/, '📈', '#2e7d4f'],\n      [/psych/, '🧠', '#9a4583'],\n      [/geograph/, '🗺️', '#4c7a5a'],\n      [/histor/, '📜', '#9a5a2a'],\n      [/statistic|\\bstats?\\b/, '📊', '#2f72a8'],\n      [/geometr|\\btrig/, '📐', '#3e64b0'],\n      [/calc|algebra|\\bmath/, '🧮', '#2f5fb3'],\n      [/english|literature|\\blit\\b|writing|composition|language arts|reading/, '📖', '#a63a4f'],\n      [/spanish|french|german|chinese|mandarin|japanese|korean|latin|italian|\\basl\\b|sign language|language/, '🗣️', '#7a4fae'],\n      [/theat|drama/, '🎭', '#a3364b'],\n      [/music|band|choir|orchestra|chorus/, '🎵', '#6b48a8'],\n      [/photo/, '📷', '#4f5d6e'],\n      [/culinary|cooking|\\bfoods?\\b|nutrition/, '🍳', '#b05a26'],\n      [/\\barts?\\b|drawing|painting|ceramic|sculpt|design/, '🎨', '#b03f7a'],\n      [/business|marketing|accounting|financ/, '💼', '#3d5f6e'],\n      [/journalism|yearbook|newspaper/, '📰', '#5c5c6e'],\n      [/science/, '🔬', '#2b7b8c'],\n    ];\n    function courseSubject(name) {\n      const n = String(name || '').toLowerCase();\n      return COURSE_SUBJECTS.find(([re]) => re.test(n)) || null;\n    }\n\n    function applyCourseCustomizationsInPlace(courses) {\n      const custom = loadCourseCustom();\n      // Mutates each course object's own fields in place (never clones,\n      // never reassigns `courses` itself) so the `const COURSES = [...]`\n      // literal a few lines below stays exactly that — a literal array —\n      // for scripts/port-pages.mjs's data-overrides transform to match\n      // and rewrite for live Schoology data. This function only edits\n      // the array's contents/order after that binding already exists.\n      courses.forEach(c => {\n        const subject = courseSubject(c.name);\n        if (subject) c.color = subject[2];\n        Object.assign(c, custom[c.id] || {});\n      });\n      const order = loadCourseOrder();\n      if (order && order.length) {\n        const byId = new Map(courses.map(c => [c.id, c]));\n        const ordered = order.filter(id => byId.has(id)).map(id => byId.get(id));\n        // A course not present in the saved order (e.g. added to the demo\n        // data after the order was saved) still shows up, just appended.\n        courses.forEach(c => { if (!order.includes(c.id)) ordered.push(c); });\n        courses.splice(0, courses.length, ...ordered);\n      }\n    }\n    const COURSES = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.COURSES) || [\n      { id: 'apchem', name: 'AP Chemistry', color: '#a67a22' },\n      { id: 'algebra2', name: 'Algebra II', color: '#5b6ea3' },\n      { id: 'english10', name: 'English 10', color: '#6b8f5e' },\n      { id: 'ushistory', name: 'U.S. History', color: '#a15c4f' },\n      { id: 'spanish3', name: 'Spanish III', color: '#8a6ba1' },\n      { id: 'pe', name: 'PE', color: '#4f8c8a' },\n    ];\n    applyCourseCustomizationsInPlace(COURSES);\n    const SCHOOL_SOURCE = { id: 'school', name: 'School & District', color: '#5c6370' };\n    const ALL_SOURCES = [...COURSES, SCHOOL_SOURCE];\n\n    // TYPE_LABEL stays granular (assignment/discussion/assessment/teacher)\n    // for anywhere a single event's specific type is displayed — the\n    // Selected Event badge, search rows, the day popover. The Created By\n    // *filter* is coarser: per Martin (2026-09-04), the three\n    // automatically-Schoology-created types (assignment/discussion/\n    // assessment) merge into one \"Assignment\" filter option, leaving just\n    // two filter chips (Assignment / Teacher-Created) — see\n    // FILTER_CATEGORIES/categoryOf below.\n    const TYPE_LABEL = { assignment: 'Assignment', discussion: 'Discussion', assessment: 'Quiz', teacher: 'Teacher-Created' };\n    const TYPES = ['assignment', 'discussion', 'assessment', 'teacher'];\n    const FILTER_CATEGORY_LABEL = { assignment: 'Assignment', teacher: 'Teacher-Created' };\n    const FILTER_CATEGORIES = ['assignment', 'teacher'];\n    function categoryOf(type) { return type === 'teacher' ? 'teacher' : 'assignment'; }\n\n    function sourceById(id) { return ALL_SOURCES.find(s => s.id === id) || SCHOOL_SOURCE; }\n\n    /**\n     * Escapes a value for interpolation into an HTML string.\n     *\n     * COURSES/EVENTS are replaced at build time with live Schoology data, and\n     * event titles, descriptions and createdBy names are written by teachers,\n     * so dropping them straight into an `.innerHTML` template would let a\n     * title like `<img src=x onerror=...>` execute in our origin. Coerces with\n     * String() rather than assuming a string, because point values arrive as\n     * numbers and nothing shape-checks the live bundle on the way in.\n     *\n     * NOTE: do not wrap values that are themselves HTML — `${actionHTML}`,\n     * `${dowRow}`, `${cellsHTML}` and the chip/row fragments are markup on\n     * purpose and escaping them would print visible tags.\n     */\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, ch => (\n        { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]\n      ));\n    }\n\n    const EVENTS = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.EVENTS) || [\n      { id: 'e1', title: 'Reading Response', date: '2026-08-19', source: 'ushistory', type: 'discussion', points: 10, desc: 'Respond to the assigned primary source reading with a 200-word reflection.', assignmentTitle: 'Reading Response' },\n      { id: 'e2', title: 'Chapter 6 Discussion', date: '2026-08-20', source: 'english10', type: 'discussion', points: 15, desc: 'Post your response to Chapter 6 and reply to two classmates.', assignmentTitle: 'Chapter 6 Discussion' },\n      { id: 'e3', title: 'Lab Report #4', date: '2026-08-21', source: 'apchem', type: 'assignment', points: 50, desc: 'Write up your findings from the titration lab, including error analysis.', assignmentTitle: 'Lab Report #4' },\n      { id: 'e4', title: 'Composición 2', date: '2026-08-21', source: 'spanish3', type: 'assignment', points: 20, desc: 'Short composition practicing preterite vs. imperfect tense.' },\n      { id: 'e5', title: 'Molarity Practice Set', date: '2026-08-22', source: 'apchem', type: 'assignment', points: 25, desc: 'Practice problems on molarity and dilution calculations.', assignmentTitle: 'Molarity Practice Set' },\n      { id: 'e6', title: 'Quiz Corrections', date: '2026-08-23', source: 'algebra2', type: 'assessment', points: 10, desc: 'Corrections for last week’s systems-of-equations quiz.', assignmentTitle: 'Quiz Corrections' },\n      { id: 'e7', title: 'Unit 2 Quiz', date: '2026-08-24', source: 'algebra2', type: 'assessment', points: 40, desc: 'Covers factoring and systems of equations.', assignmentTitle: 'Unit 2 Quiz' },\n      { id: 'e8', title: 'Titration Lab Prep', date: '2026-08-24', source: 'apchem', type: 'assignment', points: 15, desc: 'Complete the pre-lab questions before Monday’s titration lab.', assignmentTitle: 'Titration Lab Prep' },\n      { id: 'e9', title: 'Vocab Worksheet', date: '2026-08-25', source: 'spanish3', type: 'assignment', points: 15, desc: 'Unit 3 vocabulary practice worksheet.', assignmentTitle: 'Vocab Worksheet' },\n      { id: 'e10', title: 'Problem Set 7', date: '2026-08-26', source: 'algebra2', type: 'assignment', points: 30, desc: 'Problems 1–20 from the Unit 2 packet.', assignmentTitle: 'Problem Set 7' },\n      { id: 'e11', title: 'Practice Set 8', date: '2026-09-01', source: 'algebra2', type: 'assignment', points: 30, desc: 'Continued practice with systems-of-equations word problems.' },\n      { id: 'e12', title: 'Vocabulary Quiz 2', date: '2026-09-02', source: 'english10', type: 'assessment', points: 20, desc: 'Unit 2 vocabulary quiz.' },\n      { id: 'e13', title: 'Chapter 7 Discussion', date: '2026-09-03', source: 'english10', type: 'discussion', points: 15, desc: 'Post your response to Chapter 7 and reply to two classmates.' },\n      { id: 'e14', title: 'Lab Safety Refresher Quiz', date: '2026-09-04', source: 'apchem', type: 'assessment', points: 10, desc: 'Short refresher quiz before Friday’s titration lab.' },\n      { id: 'e15', title: 'Fitness Log 2', date: '2026-09-04', source: 'pe', type: 'assignment', points: 10, desc: 'Log this week’s workouts and turn in your fitness journal.' },\n      { id: 'e16', title: 'Labor Day', date: '2026-09-07', source: 'school', type: 'teacher', allDay: true, createdBy: 'District Office', desc: 'No school — district holiday.' },\n      { id: 'e17', title: 'Función de Práctica', date: '2026-09-08', source: 'spanish3', type: 'assignment', points: 15, desc: 'Practice conjugation worksheet for irregular verbs.' },\n      { id: 'e18', title: 'Progress Reports Posted', date: '2026-09-09', source: 'school', type: 'teacher', allDay: true, createdBy: 'Front Office', desc: 'Six-week progress reports are posted to PowerSchool.' },\n      { id: 'e19', title: 'Back to School Night', date: '2026-09-10', time: '6:00 PM', source: 'school', type: 'teacher', createdBy: 'Dr. Simmons, Principal', desc: 'Meet your teachers and tour the campus. Optional but encouraged.' },\n      { id: 'e20', title: 'Unit 2 Test', date: '2026-09-11', source: 'ushistory', type: 'assessment', points: 60, desc: 'Covers the Colonial Era through the Revolution.' },\n      { id: 'e21', title: 'Problem Set 9', date: '2026-09-14', source: 'algebra2', type: 'assignment', points: 30, desc: 'Problems 1–20 from the Unit 3 packet.' },\n      { id: 'e22', title: 'Lab Report #5', date: '2026-09-15', source: 'apchem', type: 'assignment', points: 50, desc: 'Write-up for the titration lab, including error analysis.' },\n      { id: 'e23', title: 'Team Strategy Quiz', date: '2026-09-16', source: 'pe', type: 'assessment', points: 10, desc: 'Short quiz on this unit’s team strategy concepts.' },\n      { id: 'e24', title: 'Essay Final Draft', date: '2026-09-17', source: 'english10', type: 'assignment', points: 75, desc: 'Final draft of your persuasive essay, with peer feedback incorporated.' },\n      { id: 'e25', title: 'Conversación Discussion', date: '2026-09-18', source: 'spanish3', type: 'discussion', points: 20, desc: 'Record a short conversation practicing this unit’s dialogue.' },\n      { id: 'e26', title: 'Colonial Timeline Presentations', date: '2026-09-21', source: 'ushistory', type: 'assignment', points: 40, desc: 'Present your group’s timeline project to the class.' },\n      { id: 'e27', title: 'Picture Day', date: '2026-09-22', source: 'school', type: 'teacher', allDay: true, createdBy: 'Front Office', desc: 'Individual and class photos — check the schedule for your period.' },\n      { id: 'e28', title: 'Unit 3 Quiz', date: '2026-09-24', source: 'algebra2', type: 'assessment', points: 40, desc: 'Covers quadratic equations.' },\n      { id: 'e29', title: 'Skills Assessment', date: '2026-09-25', source: 'pe', type: 'assessment', points: 20, desc: 'Practical skills check for this unit.' },\n      { id: 'e30', title: 'Reading Journal 2', date: '2026-09-28', source: 'english10', type: 'assignment', points: 15, desc: 'Second reading journal entry for the current novel.' },\n      { id: 'e31', title: 'Titration Lab', date: '2026-09-29', source: 'apchem', type: 'assignment', points: 35, desc: 'In-class titration lab — bring your pre-lab questions.' },\n      // The course hub's own events (2026-10-04), so an event opened from a\n      // hub lands on a real entry here. Teacher-made, like the school ones.\n      { id: 'e33', title: 'Lab Safety Demo', date: '2026-08-25', time: '10:00 AM', source: 'apchem', type: 'teacher', createdBy: 'Mr. Alvarez', desc: 'Goggles, aprons and the eyewash station, before the titration lab.' },\n      { id: 'e34', title: 'Library Day', date: '2026-08-26', time: '9:00 AM', source: 'english10', type: 'teacher', createdBy: 'Mr. Cho', desc: 'Class meets in the library. Bring your reading journal.' },\n      { id: 'e35', title: 'Mile Run', date: '2026-08-26', time: '7:45 AM', source: 'pe', type: 'teacher', createdBy: 'Coach Reyes', desc: 'Timed mile on the track. Wear running shoes.' },\n      { id: 'e36', title: 'Review Session', date: '2026-08-27', time: '3:15 PM', source: 'algebra2', type: 'teacher', createdBy: 'Ms. Whitfield', desc: 'After-school review for the Unit 2 material. Optional.' },\n      { id: 'e37', title: 'Conversation Partners', date: '2026-08-27', time: '11:30 AM', source: 'spanish3', type: 'teacher', createdBy: 'Sra. Ortiz', desc: 'Paired speaking practice in class.' },\n      { id: 'e38', title: 'Museum Field Trip Forms Due', date: '2026-08-28', time: '8:00 AM', source: 'ushistory', type: 'teacher', createdBy: 'Mrs. Bennett', desc: 'Signed permission forms are due in class.' },\n      { id: 'e32', title: 'Quarter 1 Ends', date: '2026-10-02', source: 'school', type: 'teacher', allDay: true, createdBy: 'District Office', desc: 'Last day of Quarter 1. Grades finalize at 11:59 PM.' },\n    ];\n\n    // ------------------------------------------------------------------\n    // Date helpers — events are stored as plain 'YYYY-MM-DD' strings and\n    // matched against a local-time Date's own y/m/d, so nothing here\n    // ever round-trips through a UTC-parsed Date (that's the usual\n    // source of off-by-one-day calendar bugs).\n    // ------------------------------------------------------------------\n    // ------------------------------------------------------------------\n    // Signed in (2026-10-06): EVENTS is the events extra's answer, never the\n    // samples above. A demo sign-in (which also has __AVERAGES__, with an\n    // empty bundle) shows the samples, like the preview. Each event is\n    // tidied once here; one from a class that isn't the student's (or the\n    // school's) shows as School & District rather than being filtered away.\n    // ------------------------------------------------------------------\n    const AV_LIVE = !!(window.__AVERAGES__ && window.__AVERAGES__.data) && window.__AVERAGES__.mode !== 'demo';\n    const AV_DATA = AV_LIVE ? window.__AVERAGES__.data : {};\n    if (AV_LIVE) {\n      const known = new Set(COURSES.map(c => String(c.id)));\n      const seen = new Set();\n      const tidy = (Array.isArray(AV_DATA.EVENTS) ? AV_DATA.EVENTS : []).filter(e => e && /^\\d{4}-\\d{2}-\\d{2}$/.test(String(e.date || ''))).map((e, i) => {\n        let id = String(e.id || '') || `ev${i}`;\n        if (seen.has(id)) id = `${id}-${i}`;\n        seen.add(id);\n        const source = known.has(String(e.source)) ? String(e.source) : 'school';\n        const time = e.allDay ? '' : String(e.time || '');\n        return {\n          id, title: String(e.title || '') || 'Event', date: String(e.date), source,\n          type: TYPES.includes(e.type) ? e.type : 'assignment',\n          time, allDay: !!e.allDay || (e.type === 'teacher' && !time),\n          points: Number(e.points) > 0 ? Number(e.points) : 0,\n          desc: String(e.desc || ''), createdBy: String(e.createdBy || ''),\n          assignmentId: /^\\d{1,24}$/.test(String(e.assignmentId || '')) ? String(e.assignmentId) : '',\n          assignmentTitle: String(e.assignmentTitle || ''),\n        };\n      });\n      EVENTS.splice(0, EVENTS.length, ...tidy);\n      const note = document.getElementById('calLiveNote');\n      if (!Array.isArray(AV_DATA.EVENTS)) { note.textContent = 'Your calendar events didn’t load this time. Try again in a bit.'; note.hidden = false; }\n      else if (AV_DATA.EVENTS_PARTIAL) { note.textContent = 'Some classes’ events didn’t load this time.'; note.hidden = false; }\n    }\n\n    function ymd(d) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }\n    function isSameDay(a, b) { return ymd(a) === ymd(b); }\n    function startOfDay(d) { const n = new Date(d); n.setHours(0, 0, 0, 0); return n; }\n    const TODAY = startOfDay(new Date());\n\n    function eventsOn(dateStr) { return EVENTS.filter(e => e.date === dateStr); }\n    function eventsForDate(d) { return eventsOn(ymd(d)); }\n\n    // ------------------------------------------------------------------\n    // Filter + search state.\n    // ------------------------------------------------------------------\n    const activeSources = new Set(ALL_SOURCES.map(s => s.id));\n    const activeTypes = new Set(FILTER_CATEGORIES);\n    let searchQuery = '';\n    let selectedEventId = null;\n    let currentView = 'month';\n    let focusDate = new Date(TODAY);\n\n    function passesFilters(e) {\n      if (!activeSources.has(e.source)) return false;\n      if (!activeTypes.has(categoryOf(e.type))) return false;\n      return true;\n    }\n    function matchesSearch(e) {\n      if (!searchQuery) return true;\n      const hay = `${e.title} ${sourceById(e.source).name} ${TYPE_LABEL[e.type]}`.toLowerCase();\n      return hay.includes(searchQuery);\n    }\n    function visibleEventsOn(dateStr) { return eventsOn(dateStr).filter(e => passesFilters(e) && matchesSearch(e)); }\n\n    // ------------------------------------------------------------------\n    // Filter chips.\n    // ------------------------------------------------------------------\n    function renderFilterChips() {\n      const sourceWrap = document.getElementById('sourceChips');\n      sourceWrap.innerHTML = ALL_SOURCES.map(s => `\n        <button class=\"cal-chip${activeSources.has(s.id) ? '' : ' inactive'}\" type=\"button\" data-source=\"${escapeHtml(s.id)}\">\n          <span class=\"dot\" style=\"background:${escapeHtml(s.color)}\"></span>${escapeHtml(s.name)}\n        </button>`).join('');\n      sourceWrap.querySelectorAll('.cal-chip').forEach(chip => {\n        chip.addEventListener('click', () => {\n          const id = chip.dataset.source;\n          if (activeSources.has(id)) activeSources.delete(id); else activeSources.add(id);\n          renderFilterChips();\n          renderCalendar();\n        });\n      });\n\n      const typeWrap = document.getElementById('typeChips');\n      typeWrap.innerHTML = FILTER_CATEGORIES.map(t => `\n        <button class=\"cal-chip${activeTypes.has(t) ? '' : ' inactive'}\" type=\"button\" data-type=\"${t}\">\n          <span class=\"dot\" style=\"background:var(--accent)\"></span>${FILTER_CATEGORY_LABEL[t]}\n        </button>`).join('');\n      typeWrap.querySelectorAll('.cal-chip').forEach(chip => {\n        chip.addEventListener('click', () => {\n          const t = chip.dataset.type;\n          if (activeTypes.has(t)) activeTypes.delete(t); else activeTypes.add(t);\n          renderFilterChips();\n          renderCalendar();\n        });\n      });\n\n      // Small accent dot on the Filters button itself whenever anything\n      // has been narrowed down, so it's visible without opening the panel.\n      const anyFiltered = activeSources.size < ALL_SOURCES.length || activeTypes.size < FILTER_CATEGORIES.length;\n      document.getElementById('filterActiveDot').classList.toggle('is-hidden', !anyFiltered);\n    }\n\n    // ------------------------------------------------------------------\n    // Selected Event panel.\n    // ------------------------------------------------------------------\n    const selectedCloseBtn = document.getElementById('selectedCloseBtn');\n    function renderSelectedEvent() {\n      const body = document.getElementById('selectedEventBody');\n      const event = EVENTS.find(e => e.id === selectedEventId);\n      if (!event) {\n        body.innerHTML = `<p class=\"cal-selected-empty\">Tap any event on the calendar to see its details here.</p>`;\n        selectedCloseBtn.classList.add('is-hidden');\n        return;\n      }\n      selectedCloseBtn.classList.remove('is-hidden');\n      const src = sourceById(event.source);\n      const d = new Date(event.date + 'T00:00:00');\n      const dateLabel = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });\n      // Any event created by Schoology itself (assignment/discussion/quiz —\n      // the \"Assignment\" Created By category, i.e. anything but\n      // teacher-created) gets an Open Assignment button, per Martin\n      // (2026-09-04) — not just the 10 events pre-linked to a real\n      // /assignment record via assignmentTitle. /assignment's own\n      // ?course=&title= routing already has a graceful fallback for a\n      // title/course pair it doesn't recognize (shows the real title with\n      // generic content instead of erroring), so this is safe to link\n      // for every Assignment-category event, not just the flagged ones.\n      let actionHTML = '';\n      if (AV_LIVE && event.assignmentId) {\n        // Signed in: the exact assignment (2026-10-06).\n        const linkTitle = event.assignmentTitle || event.title;\n        actionHTML = `<div class=\"cal-selected-actions\"><a class=\"cal-selected-view-btn\" href=\"/assignment?course=${encodeURIComponent(event.source)}&id=${encodeURIComponent(event.assignmentId)}&title=${encodeURIComponent(linkTitle)}\">Open Assignment</a></div>`;\n      } else if (AV_LIVE) {\n        // Not something to turn in (or not one we can open): its class.\n        if (event.source !== 'school') actionHTML = `<div class=\"cal-selected-actions\"><a class=\"cal-selected-view-btn\" href=\"/course-home?course=${encodeURIComponent(event.source)}\">View Course</a></div>`;\n      } else if (event.type !== 'teacher') {\n        const linkTitle = event.assignmentTitle || event.title;\n        actionHTML = `<div class=\"cal-selected-actions\"><a class=\"cal-selected-view-btn\" href=\"/assignment?course=${encodeURIComponent(event.source)}&title=${encodeURIComponent(linkTitle)}\">Open Assignment</a></div>`;\n      } else if (event.source !== 'school') {\n        actionHTML = `<div class=\"cal-selected-actions\"><a class=\"cal-selected-view-btn\" href=\"/course-home?course=${encodeURIComponent(event.source)}\">View Course</a></div>`;\n      }\n      body.innerHTML = `\n        <p class=\"cal-selected-title\">${escapeHtml(event.title)}</p>\n        <p class=\"cal-selected-course\"><span class=\"dot\" style=\"background:${escapeHtml(src.color)}\"></span>${escapeHtml(src.name)}</p>\n        ${event.type === 'teacher' && event.createdBy\n          ? `<span class=\"cal-selected-badge has-tooltip\" tabindex=\"0\">${TYPE_LABEL[event.type]}<span class=\"cal-tooltip\" role=\"tooltip\">Created by ${escapeHtml(event.createdBy)}</span></span>`\n          : `<span class=\"cal-selected-badge\">${TYPE_LABEL[event.type]}</span>`}\n        <div class=\"cal-selected-row\"><span class=\"k\">Date</span><span class=\"v\">${escapeHtml(dateLabel)}</span></div>\n        <div class=\"cal-selected-row\"><span class=\"k\">Time</span><span class=\"v\">${event.allDay ? 'All day' : escapeHtml(event.time || 'Due 11:59 PM')}</span></div>\n        ${event.points ? `<div class=\"cal-selected-row\"><span class=\"k\">Points</span><span class=\"v\">${escapeHtml(event.points)} pts</span></div>` : ''}\n        ${event.desc ? `<p class=\"cal-selected-desc\">${escapeHtml(event.desc)}</p>` : ''}\n        ${actionHTML}\n      `;\n    }\n    // renderCalendar() re-runs on every selection change so the grid\n    // itself can show *where* the selected event is (2026-09-04, per\n    // Martin) — not just the sidebar panel. Cheap at this data scale, and\n    // consistent with how renderFilterChips()/renderCalendar() already\n    // do a full re-render on every other state change in this file.\n    function selectEvent(id) { selectedEventId = id; renderSelectedEvent(); closeDayModal(); renderCalendar(); }\n    selectedCloseBtn.addEventListener('click', () => { selectedEventId = null; renderSelectedEvent(); renderCalendar(); });\n\n    // ------------------------------------------------------------------\n    // Day popover modal — lists every (filtered) event on one date.\n    // ------------------------------------------------------------------\n    const dayModal = document.getElementById('dayModal');\n    function openDayModal(dateStr) {\n      const d = new Date(dateStr + 'T00:00:00');\n      document.getElementById('dayModalTitle').textContent = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });\n      const items = visibleEventsOn(dateStr);\n      document.getElementById('dayModalList').innerHTML = items.length\n        ? items.map(e => {\n            const src = sourceById(e.source);\n            return `<button class=\"cal-search-row${e.id === selectedEventId ? ' selected' : ''}\" type=\"button\" data-id=\"${escapeHtml(e.id)}\">\n              <span class=\"dot\" style=\"background:${escapeHtml(src.color)}\"></span>\n              <span class=\"cal-search-row-text\">\n                <p class=\"cal-search-row-title\">${escapeHtml(e.title)}</p>\n                <p class=\"cal-search-row-meta\">${escapeHtml(src.name)} · ${TYPE_LABEL[e.type]}</p>\n              </span>\n            </button>`;\n          }).join('')\n        : `<p class=\"cal-empty-note\">No events match your filters on this day.</p>`;\n      document.getElementById('dayModalList').querySelectorAll('.cal-search-row').forEach(row => {\n        row.addEventListener('click', () => selectEvent(row.dataset.id));\n      });\n      dayModal.classList.add('show');\n      document.getElementById('dayModalCloseBtn').focus();\n    }\n    function closeDayModal() { dayModal.classList.remove('show'); }\n    document.getElementById('dayModalCloseBtn').addEventListener('click', closeDayModal);\n    dayModal.addEventListener('click', e => { if (e.target === dayModal) closeDayModal(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && dayModal.classList.contains('show')) closeDayModal(); });\n\n    // ------------------------------------------------------------------\n    // Month view.\n    // ------------------------------------------------------------------\n    function buildMonthCells(year, month) {\n      const firstOfMonth = new Date(year, month, 1);\n      const startDow = firstOfMonth.getDay();\n      const daysInMonth = new Date(year, month + 1, 0).getDate();\n      const daysInPrevMonth = new Date(year, month, 0).getDate();\n      const cells = [];\n      for (let i = startDow - 1; i >= 0; i--) cells.push({ date: new Date(year, month - 1, daysInPrevMonth - i), outside: true });\n      for (let d = 1; d <= daysInMonth; d++) cells.push({ date: new Date(year, month, d), outside: false });\n      while (cells.length % 7 !== 0) {\n        const last = cells[cells.length - 1].date;\n        cells.push({ date: new Date(last.getFullYear(), last.getMonth(), last.getDate() + 1), outside: true });\n      }\n      return cells;\n    }\n\n    function eventChipHTML(e) {\n      const src = sourceById(e.source);\n      const cls = ['cal-event-chip', e.source === 'school' ? 'school' : '', e.id === selectedEventId ? 'selected' : ''].filter(Boolean).join(' ');\n      return `<button class=\"${cls}\" style=\"--chip-color:${escapeHtml(src.color)}\" type=\"button\" data-id=\"${escapeHtml(e.id)}\" title=\"${escapeHtml(e.title)}\">${escapeHtml(e.title)}</button>`;\n    }\n\n    function renderMonthView() {\n      const cells = buildMonthCells(focusDate.getFullYear(), focusDate.getMonth());\n      const DOW = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];\n      const dowRow = `<div class=\"cal-dow-row\">${DOW.map(d => `<div class=\"cal-dow-cell\">${d}</div>`).join('')}</div>`;\n      const cellsHTML = cells.map(cell => {\n        const dateStr = ymd(cell.date);\n        const items = visibleEventsOn(dateStr);\n        const shown = items.slice(0, 3);\n        const more = items.length - shown.length;\n        const hasSelected = items.some(e => e.id === selectedEventId);\n        return `\n          <div class=\"cal-day-cell${cell.outside ? ' outside' : ''}${isSameDay(cell.date, TODAY) ? ' is-today' : ''}${hasSelected ? ' has-selected' : ''}\" data-date=\"${dateStr}\">\n            <span class=\"cal-day-num\">${cell.date.getDate()}</span>\n            <div class=\"cal-day-events\">\n              ${shown.map(eventChipHTML).join('')}\n              ${more > 0 ? `<button class=\"cal-day-more\" type=\"button\" data-date=\"${dateStr}\">+${more} more</button>` : ''}\n            </div>\n          </div>`;\n      }).join('');\n      document.getElementById('calBody').innerHTML = `<div class=\"cal-grid-wrap\">${dowRow}<div class=\"cal-month-grid\">${cellsHTML}</div></div>`;\n      // Header just names the month (e.g. \"September\") — the year has its\n      // own dedicated view (below) rather than being repeated here, per\n      // Martin's spec for the toolbar header (2026-09-04).\n      document.getElementById('calHeaderLabel').textContent = focusDate.toLocaleDateString('en-US', { month: 'long' });\n      wireGridClicks();\n    }\n\n    // ------------------------------------------------------------------\n    // Week view.\n    // ------------------------------------------------------------------\n    function startOfWeek(d) { const n = new Date(d); n.setDate(n.getDate() - n.getDay()); return startOfDay(n); }\n\n    function renderWeekView() {\n      const weekStart = startOfWeek(focusDate);\n      const DOW = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];\n      const dowRow = `<div class=\"cal-dow-row\">${DOW.map((d, i) => {\n        const day = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + i);\n        return `<div class=\"cal-dow-cell\">${d} ${day.getDate()}</div>`;\n      }).join('')}</div>`;\n      const cellsHTML = Array.from({ length: 7 }, (_, i) => {\n        const day = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + i);\n        const dateStr = ymd(day);\n        const items = visibleEventsOn(dateStr);\n        const hasSelected = items.some(e => e.id === selectedEventId);\n        return `\n          <div class=\"cal-week-cell${isSameDay(day, TODAY) ? ' is-today' : ''}${hasSelected ? ' has-selected' : ''}\" data-date=\"${dateStr}\">\n            <span class=\"cal-day-num\">${day.getDate()}</span>\n            <div class=\"cal-day-events\">\n              ${items.length ? items.map(eventChipHTML).join('') : '<p class=\"cal-week-empty\">None</p>'}\n            </div>\n          </div>`;\n      }).join('');\n      document.getElementById('calBody').innerHTML = `<div class=\"cal-grid-wrap\">${dowRow}<div class=\"cal-week-grid\">${cellsHTML}</div></div>`;\n      // Header reads \"Week of {the Monday of this week}\" per Martin's spec\n      // (2026-09-04) — the grid itself still starts on Sunday (unchanged),\n      // this just always names the Monday two days in, regardless of\n      // which day of the week is actually the anchor.\n      const monday = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + 1);\n      const mondayLabel = monday.toLocaleDateString('en-US', { month: 'long', day: 'numeric' });\n      document.getElementById('calHeaderLabel').textContent = `Week of ${mondayLabel}`;\n      wireGridClicks();\n    }\n\n    // ------------------------------------------------------------------\n    // Year view — 12 mini months; click a mini day (or the month label)\n    // to jump into Month view for that month.\n    // ------------------------------------------------------------------\n    function renderYearView() {\n      const year = focusDate.getFullYear();\n      const months = Array.from({ length: 12 }, (_, m) => {\n        const label = new Date(year, m, 1).toLocaleDateString('en-US', { month: 'long' });\n        const cells = buildMonthCells(year, m);\n        const dow = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];\n        return `\n          <div class=\"cal-mini-month\" data-year=\"${year}\" data-month=\"${m}\">\n            <p class=\"cal-mini-month-label\">${label}</p>\n            <div class=\"cal-mini-dow-row\">${dow.map(d => `<div class=\"cal-mini-dow\">${d}</div>`).join('')}</div>\n            ${chunk(cells, 7).map(week => `<div class=\"cal-mini-week-row\">${week.map(cell => {\n              const dayItems = cell.outside ? [] : visibleEventsOn(ymd(cell.date));\n              const hasEvent = dayItems.length > 0;\n              const hasSelected = dayItems.some(e => e.id === selectedEventId);\n              return `<div class=\"cal-mini-day${cell.outside ? ' outside' : ''}${isSameDay(cell.date, TODAY) ? ' is-today' : ''}${hasEvent ? ' has-event' : ''}${hasSelected ? ' has-selected' : ''}\">${cell.date.getDate()}</div>`;\n            }).join('')}</div>`).join('')}\n          </div>`;\n      }).join('');\n      document.getElementById('calBody').innerHTML = `<div class=\"cal-year-grid\">${months}</div>`;\n      document.getElementById('calHeaderLabel').textContent = String(year);\n      document.querySelectorAll('.cal-mini-month').forEach(m => {\n        m.addEventListener('click', () => {\n          focusDate = new Date(Number(m.dataset.year), Number(m.dataset.month), 1);\n          currentView = 'month';\n          setActiveViewButton('month');\n          renderCalendar();\n        });\n      });\n    }\n    function chunk(arr, size) { const out = []; for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size)); return out; }\n\n    // ------------------------------------------------------------------\n    // Search results view — a flat, date-sorted list across ALL events\n    // (not just the visible range), replacing the grid while a query is\n    // active.\n    // ------------------------------------------------------------------\n    function renderSearchResults() {\n      const items = EVENTS.filter(e => passesFilters(e) && matchesSearch(e)).sort((a, b) => a.date.localeCompare(b.date));\n      document.getElementById('calHeaderLabel').textContent = `${items.length} result${items.length === 1 ? '' : 's'}`;\n      if (!items.length) {\n        document.getElementById('calBody').innerHTML = `<div class=\"cal-grid-wrap\"><p class=\"cal-empty-note\">No events match \"${escapeHtml(searchQuery)}\".</p></div>`;\n        return;\n      }\n      const rows = items.map(e => {\n        const src = sourceById(e.source);\n        const d = new Date(e.date + 'T00:00:00');\n        const dateLabel = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });\n        return `<button class=\"cal-search-row${e.id === selectedEventId ? ' selected' : ''}\" type=\"button\" data-id=\"${escapeHtml(e.id)}\">\n          <span class=\"dot\" style=\"background:${escapeHtml(src.color)}\"></span>\n          <span class=\"cal-search-row-text\">\n            <p class=\"cal-search-row-title\">${escapeHtml(e.title)}</p>\n            <p class=\"cal-search-row-meta\">${escapeHtml(dateLabel)} · ${escapeHtml(src.name)} · ${TYPE_LABEL[e.type]}</p>\n          </span>\n        </button>`;\n      }).join('');\n      document.getElementById('calBody').innerHTML = `<div class=\"cal-grid-wrap\"><div class=\"cal-search-results\">${rows}</div></div>`;\n      document.querySelectorAll('.cal-search-row').forEach(row => {\n        row.addEventListener('click', () => selectEvent(row.dataset.id));\n      });\n    }\n\n    // ------------------------------------------------------------------\n    // Dispatcher + shared click wiring for the month/week grids.\n    // ------------------------------------------------------------------\n    function wireGridClicks() {\n      document.querySelectorAll('.cal-event-chip').forEach(chip => {\n        chip.addEventListener('click', e => { e.stopPropagation(); selectEvent(chip.dataset.id); });\n      });\n      document.querySelectorAll('.cal-day-more').forEach(btn => {\n        btn.addEventListener('click', e => { e.stopPropagation(); openDayModal(btn.dataset.date); });\n      });\n    }\n\n    function renderCalendar() {\n      if (searchQuery) { renderSearchResults(); return; }\n      if (currentView === 'month') renderMonthView();\n      else if (currentView === 'week') renderWeekView();\n      else renderYearView();\n    }\n\n    // ------------------------------------------------------------------\n    // Toolbar wiring: view switch, prev/next, today, search.\n    // ------------------------------------------------------------------\n    function setActiveViewButton(view) {\n      document.querySelectorAll('.cal-view-btn').forEach(b => b.classList.toggle('active', b.dataset.view === view));\n    }\n    document.getElementById('viewSwitch').addEventListener('click', e => {\n      const btn = e.target.closest('.cal-view-btn');\n      if (!btn) return;\n      currentView = btn.dataset.view;\n      setActiveViewButton(currentView);\n      renderCalendar();\n    });\n\n    document.getElementById('calPrevBtn').addEventListener('click', () => { step(-1); });\n    document.getElementById('calNextBtn').addEventListener('click', () => { step(1); });\n    function step(dir) {\n      if (currentView === 'month') focusDate = new Date(focusDate.getFullYear(), focusDate.getMonth() + dir, 1);\n      else if (currentView === 'week') focusDate = new Date(focusDate.getFullYear(), focusDate.getMonth(), focusDate.getDate() + dir * 7);\n      else focusDate = new Date(focusDate.getFullYear() + dir, focusDate.getMonth(), 1);\n      renderCalendar();\n    }\n    document.getElementById('calTodayBtn').addEventListener('click', () => { focusDate = new Date(TODAY); renderCalendar(); });\n\n    // ------------------------------------------------------------------\n    // Filter dropdown — Source + Created By chips, moved off the sidebar\n    // and into one popover next to Today (2026-09-04, per Martin). Same\n    // open/close-on-outside-click/Escape pattern as the profile menu.\n    // ------------------------------------------------------------------\n    const filterBtn = document.getElementById('filterBtn');\n    const filterPanel = document.getElementById('filterPanel');\n    function openFilterPanel() { filterPanel.classList.remove('is-hidden'); filterBtn.setAttribute('aria-expanded', 'true'); }\n    function closeFilterPanel() { filterPanel.classList.add('is-hidden'); filterBtn.setAttribute('aria-expanded', 'false'); }\n    filterBtn.addEventListener('click', () => { if (filterPanel.classList.contains('is-hidden')) openFilterPanel(); else closeFilterPanel(); });\n    document.addEventListener('click', e => {\n      if (filterPanel.classList.contains('is-hidden')) return;\n      // Toggling a chip inside the panel re-renders the chip list\n      // (renderFilterChips replaces sourceChips/typeChips' innerHTML),\n      // which detaches the clicked button from the DOM before this\n      // bubbled listener runs — e.target.closest(...) would then find\n      // nothing and wrongly read the click as \"outside.\" composedPath()\n      // is captured at dispatch time, before that mutation, so it still\n      // correctly reflects the click's real ancestry.\n      const wrap = document.querySelector('.cal-filter-dropdown-wrap');\n      if (!e.composedPath().includes(wrap)) closeFilterPanel();\n    });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !filterPanel.classList.contains('is-hidden')) { closeFilterPanel(); filterBtn.focus(); } });\n\n    const searchInput = document.getElementById('calendarSearch');\n    const searchClearBtn = document.getElementById('calendarSearchClear');\n    searchInput.addEventListener('input', () => {\n      searchQuery = searchInput.value.trim().toLowerCase();\n      searchClearBtn.classList.toggle('is-hidden', !searchQuery);\n      renderCalendar();\n    });\n    searchClearBtn.addEventListener('click', () => {\n      searchInput.value = '';\n      searchQuery = '';\n      searchClearBtn.classList.add('is-hidden');\n      renderCalendar();\n      searchInput.focus();\n    });\n\n    // ------------------------------------------------------------------\n    // Dark mode — same token-swap convention as /settings/\n    // /onboard, extended with --cal-grid-bg/--cal-cell-alt so the\n    // calendar surface itself flips from white to near-black (per\n    // Martin, 2026-09-04) while --accent stays fixed and does the\n    // highlighting in both modes. No manual page-local toggle (removed\n    // 2026-09-04, per Martin) — this page only ever follows a setting\n    // decided elsewhere.\n    //\n    // Fixed 2026-09-07: \"elsewhere\" used to mean the OS's own\n    // prefers-color-scheme, checked fresh on every load with no memory\n    // of anything — so Calendar could be dark while every other page\n    // stayed light (or the reverse), independent of whatever Settings'\n    // real Dark Mode toggle was set to. Now it reads the same\n    // schoolagy_dark_mode localStorage flag Settings writes, falling\n    // back to the OS only when nothing's been explicitly chosen yet —\n    // so this page agrees with the rest of the app instead of running\n    // its own separate check.\n    // ------------------------------------------------------------------\n    const AVERAGES_DARK_MODE_KEY = 'schoolagy_dark_mode';\n    function averagesSavedDarkPref() {\n      try {\n        const v = localStorage.getItem(AVERAGES_DARK_MODE_KEY);\n        if (v === 'dark') return true;\n        if (v === 'light') return false;\n      } catch {}\n      return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;\n    }\n    function applyDarkMode(isDark) {\n      const root = document.documentElement.style;\n      if (isDark) {\n        root.setProperty('--panel-bg', '#1c1d26');\n        root.setProperty('--panel-inner', '#15161e');\n        root.setProperty('--text-dark', '#f0f0f5');\n        root.setProperty('--text-muted', '#a3a5bd');\n        root.setProperty('--text-faint', '#6f7086');\n        root.setProperty('--border', '#33344a');\n        root.setProperty('--toggle-track-bg', '#3a3c4d');\n        root.setProperty('--cal-grid-bg', '#0b0b10');\n        root.setProperty('--cal-cell-alt', '#131319');\n      } else {\n        root.setProperty('--panel-bg', '#eaeaec');\n        root.setProperty('--panel-inner', '#dcdce0');\n        root.setProperty('--text-dark', '#14151f');\n        root.setProperty('--text-muted', '#4b4d63');\n        root.setProperty('--text-faint', '#83849a');\n        root.setProperty('--border', '#cfcfd6');\n        root.setProperty('--toggle-track-bg', '#c7c7cd');\n        root.setProperty('--cal-grid-bg', '#ffffff');\n        root.setProperty('--cal-cell-alt', '#f4f4f6');\n      }\n      document.body.classList.toggle('dark-mode', isDark);\n    }\n    applyDarkMode(averagesSavedDarkPref());\n    // A Settings-toggle change (or another tab) should reflect here live,\n    // since this page has no toggle of its own to re-trigger a load.\n    window.addEventListener('storage', e => {\n      if (e.key === AVERAGES_DARK_MODE_KEY) applyDarkMode(averagesSavedDarkPref());\n    });\n\n    // ------------------------------------------------------------------\n    // Nav — Home/Courses/Grades/Assignments/Messages/Contacts/Settings\n    // are real links between real pages; Calendar is this page itself.\n    // ------------------------------------------------------------------\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) { window.location.href = link.dataset.href; return; }\n        document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));\n        link.classList.add('active');\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — same behavior as every other page.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    // Shared profile photo/name (2026-09-07) — /settings's Edit\n    // Profile modal is the only place this is ever set, but every other\n    // page's top-right profile button used to just show a fixed \"M\" no\n    // matter what was saved there: the button never read anything back,\n    // so a photo you set in Settings was invisible the moment you left\n    // it. schoolagy_profile is the same localStorage record\n    // /settings writes on every save; this is read-only here.\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('schoolagy_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile) return;\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n      } else if (profile.name) {\n        profileBtn.textContent = profile.name.trim().charAt(0).toUpperCase() || 'M';\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n    function openProfileMenu() { profileMenu.hidden = false; profileBtn.setAttribute('aria-expanded', 'true'); }\n    function closeProfileMenu() { profileMenu.hidden = true; profileBtn.setAttribute('aria-expanded', 'false'); }\n    profileBtn.addEventListener('click', () => { if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu(); });\n    document.addEventListener('click', e => { if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); } });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Initial render.\n    // ------------------------------------------------------------------\n    renderFilterChips();\n    renderSelectedEvent();\n    renderCalendar();\n    // Opened from a course hub (2026-10-04): ?date=YYYY-MM-DD jumps to that\n    // date, and ?event=&course= selects the matching event. Its course and\n    // type are switched back on in the filters so it can't be hidden.\n    (function () {\n      const q = new URLSearchParams(location.search);\n      const date = q.get('date');\n      if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(date || '')) return;\n      const [y, m, d] = date.split('-').map(Number);\n      const when = new Date(y, m - 1, d);\n      if (isNaN(when)) return;\n      focusDate = when;\n      const title = q.get('event'), src = q.get('course'), id = q.get('id');\n      // The exact event when the hub sent its id (2026-10-06), else by title.\n      const ev = (id && EVENTS.find(e => e.id === id && e.date === date)) || (title && EVENTS.find(e => e.date === date && e.title === title && (!src || e.source === src)));\n      if (ev) {\n        activeSources.add(ev.source);\n        activeTypes.add(categoryOf(ev.type));\n        renderFilterChips();\n        selectedEventId = ev.id;\n        renderSelectedEvent();\n      }\n      renderCalendar();\n      if (ev && window.matchMedia('(max-width: 900px)').matches) {\n        const panel = document.getElementById('selectedEventBody');\n        if (panel) panel.scrollIntoView({ block: 'nearest' });\n      }\n    })();\n  \n\n\n    // Back link (2026-10-01, per Martin: \"where it returns to ... is always\n    // wrong\"). Every page records itself in a short per-tab trail; a page's\n    // back link then says and goes to the page before it (\"Back to AP\n    // Chemistry Hub\", \"Back to Grades\"...). With no trail (the page was\n    // opened directly) the page's own default back link is left alone.\n    (function () {\n      const SELF = '/calendar';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Calendar';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

export default function Page() {
  return (
    <LegacyPage
      title={TITLE}
      styleCss={STYLE_CSS}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      requiresAuth={true}
      usesSavedTheme={true}
      hasUploads={false}
      externalScripts={[]}
      pageId={"calendar"}
    />
  );
}
